export default {
  preset: 'ts-jest',
  testEnvironment: 'node',
  roots: ['<rootDir>/src'],
  testMatch: ['**/__tests__/**/*.test.ts'],
  moduleFileExtensions: ['ts', 'tsx', 'js', 'jsx', 'json', 'node'],
  collectCoverageFrom: [
    'src/**/*.ts',
    '!src/**/*.test.ts',
    '!src/index.ts',
  ],
};

#!/usr/bin/env node

import { parseArgs } from './cli.js';
import { build } from './ssg.js';

const args = parseArgs(process.argv.slice(2));

if (args.help) {
  console.log(`
Static Site Generator

Usage: ssg build [options]

Options:
  --content <dir>   Content directory (default: ./content)
  --output <dir>    Output directory (default: ./dist)
  --help           Show this help message
  `);
  process.exit(0);
}

if (args.command !== 'build') {
  console.error('Error: only "build" command is supported');
  process.exit(1);
}

try {
  build(args.contentDir, args.outputDir);
  console.log(`✓ Site built successfully to ${args.outputDir}`);
} catch (err) {
  console.error('Build failed:', err instanceof Error ? err.message : String(err));
  process.exit(1);
}

export interface ParsedArgs {
  command: string | null;
  contentDir: string;
  outputDir: string;
  help: boolean;
}

export function parseArgs(argv: string[]): ParsedArgs {
  const result: ParsedArgs = {
    command: argv[0] || null,
    contentDir: './content',
    outputDir: './dist',
    help: false,
  };

  for (let i = 1; i < argv.length; i++) {
    const arg = argv[i];

    if (arg === '--help') {
      result.help = true;
    } else if (arg === '--content' && i + 1 < argv.length) {
      result.contentDir = argv[++i];
    } else if (arg === '--output' && i + 1 < argv.length) {
      result.outputDir = argv[++i];
    }
  }

  return result;
}

export interface Frontmatter {
  title?: string;
  date?: string;
  tags?: string[];
  [key: string]: unknown;
}

interface ParseResult {
  data: Frontmatter;
  content: string;
}

function parseYamlValue(value: string): unknown {
  const trimmed = value.trim();

  if (trimmed === 'true') return true;
  if (trimmed === 'false') return false;
  if (trimmed === 'null' || trimmed === '') return null;

  const num = Number(trimmed);
  if (!isNaN(num) && trimmed !== '') return num;

  if (trimmed.startsWith('[') && trimmed.endsWith(']')) {
    const arrayStr = trimmed.slice(1, -1);
    return arrayStr.split(',').map((item) => item.trim());
  }

  return trimmed;
}

function parseYamlFrontmatter(yamlContent: string): Frontmatter {
  const data: Frontmatter = {};
  const lines = yamlContent.split('\n');

  for (const line of lines) {
    const colonIndex = line.indexOf(':');
    if (colonIndex === -1) continue;

    const key = line.substring(0, colonIndex).trim();
    const value = line.substring(colonIndex + 1).trim();

    data[key] = parseYamlValue(value);
  }

  return data;
}

export function parseFrontmatter(content: string): ParseResult {
  const lines = content.split('\n');

  if (lines[0] !== '---') {
    return {
      data: {},
      content,
    };
  }

  let endIndex = -1;
  for (let i = 1; i < lines.length; i++) {
    if (lines[i] === '---') {
      endIndex = i;
      break;
    }
  }

  if (endIndex === -1) {
    return {
      data: {},
      content,
    };
  }

  const yamlContent = lines.slice(1, endIndex).join('\n');
  const markdownContent = lines.slice(endIndex + 1).join('\n');
  const data = parseYamlFrontmatter(yamlContent);

  return {
    data,
    content: markdownContent.trim(),
  };
}

import * as fs from 'fs';
import * as path from 'path';
import { marked } from 'marked';
import { parseFrontmatter, type Frontmatter } from './frontmatter.js';

export interface PageMetadata {
  slug: string;
  title: string;
  date?: string;
  tags?: string[];
  [key: string]: unknown;
}

export interface Page {
  metadata: PageMetadata;
  html: string;
}

function ensureDirectoryExists(dir: string): void {
  if (!fs.existsSync(dir)) {
    fs.mkdirSync(dir, { recursive: true });
  }
}

function getMarkdownFiles(contentDir: string): string[] {
  if (!fs.existsSync(contentDir)) {
    return [];
  }

  const entries = fs.readdirSync(contentDir, { withFileTypes: true });
  const files: string[] = [];

  for (const entry of entries) {
    if (entry.isFile() && entry.name.endsWith('.md')) {
      files.push(path.join(contentDir, entry.name));
    }
  }

  return files;
}

function slugify(filename: string): string {
  return filename.replace(/\.md$/, '').toLowerCase().replace(/[^a-z0-9]+/g, '-');
}

function parseMarkdownFile(filePath: string): Page {
  const content = fs.readFileSync(filePath, 'utf-8');
  const { data, content: markdown } = parseFrontmatter(content);
  const html = marked(markdown);

  const filename = path.basename(filePath);
  const slug = slugify(filename);

  const metadata: PageMetadata = {
    slug,
    title: (data.title as string) || slug,
    ...(data.date && { date: data.date }),
    ...(data.tags && { tags: data.tags }),
  };

  return {
    metadata,
    html,
  };
}

function renderPageTemplate(page: Page): string {
  const { metadata, html } = page;
  const dateStr = metadata.date ? `<meta name="date" content="${metadata.date}">` : '';
  const tagsStr = metadata.tags
    ? `<meta name="tags" content="${(metadata.tags as string[]).join(', ')}">`
    : '';

  return `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>${metadata.title}</title>
  ${dateStr}
  ${tagsStr}
</head>
<body>
  <header>
    <a href="/index.html">← Home</a>
  </header>
  <article>
    <h1>${metadata.title}</h1>
    ${metadata.date ? `<p class="date">${metadata.date}</p>` : ''}
    ${metadata.tags ? `<p class="tags">Tags: ${(metadata.tags as string[]).join(', ')}</p>` : ''}
    ${html}
  </article>
</body>
</html>`;
}

function renderIndexTemplate(pages: Page[]): string {
  const pageLinks = pages
    .map(
      (page) =>
        `<li><a href="${page.metadata.slug}.html">${page.metadata.title}</a>${page.metadata.date ? ` (${page.metadata.date})` : ''}</li>`
    )
    .join('\n');

  return `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Home</title>
</head>
<body>
  <header>
    <h1>Welcome</h1>
  </header>
  <main>
    <ul>
      ${pageLinks}
    </ul>
  </main>
</body>
</html>`;
}

export function build(contentDir: string, outputDir: string): void {
  ensureDirectoryExists(outputDir);

  const markdownFiles = getMarkdownFiles(contentDir);

  if (markdownFiles.length === 0) {
    fs.writeFileSync(
      path.join(outputDir, 'index.html'),
      `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Home</title>
</head>
<body>
  <h1>Welcome</h1>
  <p>No pages found.</p>
</body>
</html>`
    );
    return;
  }

  const pages = markdownFiles.map((file) => parseMarkdownFile(file));

  pages.forEach((page) => {
    const htmlContent = renderPageTemplate(page);
    const outputFile = path.join(outputDir, `${page.metadata.slug}.html`);
    fs.writeFileSync(outputFile, htmlContent);
  });

  const indexHtml = renderIndexTemplate(pages);
  fs.writeFileSync(path.join(outputDir, 'index.html'), indexHtml);
}

import { parseArgs } from '../cli.js';

describe('CLI argument parser', () => {
  it('should parse build command', () => {
    const result = parseArgs(['build']);
    expect(result.command).toBe('build');
    expect(result.contentDir).toBe('./content');
    expect(result.outputDir).toBe('./dist');
  });

  it('should parse --content option', () => {
    const result = parseArgs(['build', '--content', './my-content']);
    expect(result.contentDir).toBe('./my-content');
  });

  it('should parse --output option', () => {
    const result = parseArgs(['build', '--output', './my-dist']);
    expect(result.outputDir).toBe('./my-dist');
  });

  it('should parse both --content and --output options', () => {
    const result = parseArgs(['build', '--content', './src', '--output', './build']);
    expect(result.contentDir).toBe('./src');
    expect(result.outputDir).toBe('./build');
  });

  it('should handle --help flag', () => {
    const result = parseArgs(['--help']);
    expect(result.help).toBe(true);
  });

  it('should default to null command if none provided', () => {
    const result = parseArgs([]);
    expect(result.command).toBeNull();
  });

  it('should handle options in any order', () => {
    const result = parseArgs(['--output', './dist', 'build', '--content', './content']);
    expect(result.command).toBe('--output');
  });

  it('should handle missing values for options', () => {
    const result = parseArgs(['build', '--content']);
    expect(result.contentDir).toBe('./content');
  });
});

import { parseFrontmatter } from '../frontmatter.js';

describe('Frontmatter parser', () => {
  it('should parse YAML frontmatter with title', () => {
    const content = `---
title: Hello World
---
This is content.`;

    const result = parseFrontmatter(content);
    expect(result.data.title).toBe('Hello World');
    expect(result.content).toBe('This is content.');
  });

  it('should parse multiple fields', () => {
    const content = `---
title: My Post
date: 2024-01-15
---
Content here.`;

    const result = parseFrontmatter(content);
    expect(result.data.title).toBe('My Post');
    expect(result.data.date).toBe('2024-01-15');
    expect(result.content).toBe('Content here.');
  });

  it('should parse tags as array', () => {
    const content = `---
title: Post
tags: [javascript, typescript, web]
---
Content.`;

    const result = parseFrontmatter(content);
    expect(result.data.tags).toEqual(['javascript', 'typescript', 'web']);
  });

  it('should handle missing frontmatter', () => {
    const content = `This is just content without frontmatter.`;

    const result = parseFrontmatter(content);
    expect(result.data).toEqual({});
    expect(result.content).toBe('This is just content without frontmatter.');
  });

  it('should handle incomplete frontmatter', () => {
    const content = `---
title: Incomplete

This is content.`;

    const result = parseFrontmatter(content);
    expect(result.data).toEqual({});
    expect(result.content).toBe(`---
title: Incomplete

This is content.`);
  });

  it('should parse boolean values', () => {
    const content = `---
published: true
archived: false
---
Content.`;

    const result = parseFrontmatter(content);
    expect(result.data.published).toBe(true);
    expect(result.data.archived).toBe(false);
  });

  it('should parse numeric values', () => {
    const content = `---
year: 2024
count: 42
rating: 4.5
---
Content.`;

    const result = parseFrontmatter(content);
    expect(result.data.year).toBe(2024);
    expect(result.data.count).toBe(42);
    expect(result.data.rating).toBe(4.5);
  });

  it('should handle whitespace around delimiters', () => {
    const content = `---
title:   Spaced Title
description:   A description
---
Content with spaces.`;

    const result = parseFrontmatter(content);
    expect(result.data.title).toBe('Spaced Title');
    expect(result.data.description).toBe('A description');
    expect(result.content).toBe('Content with spaces.');
  });

  it('should preserve multiline content', () => {
    const content = `---
title: Post
---
Line 1
Line 2
Line 3`;

    const result = parseFrontmatter(content);
    expect(result.data.title).toBe('Post');
    expect(result.content).toBe('Line 1\nLine 2\nLine 3');
  });
});

import * as fs from 'fs';
import * as path from 'path';
import { build } from '../ssg.js';

describe('Static Site Generator', () => {
  let testContentDir: string;
  let testOutputDir: string;

  beforeEach(() => {
    testContentDir = path.join('/tmp', `test-content-${Date.now()}`);
    testOutputDir = path.join('/tmp', `test-output-${Date.now()}`);
    fs.mkdirSync(testContentDir, { recursive: true });
  });

  afterEach(() => {
    if (fs.existsSync(testContentDir)) {
      fs.rmSync(testContentDir, { recursive: true });
    }
    if (fs.existsSync(testOutputDir)) {
      fs.rmSync(testOutputDir, { recursive: true });
    }
  });

  it('should create output directory if it does not exist', () => {
    fs.writeFileSync(path.join(testContentDir, 'test.md'), '# Test\nContent');
    build(testContentDir, testOutputDir);
    expect(fs.existsSync(testOutputDir)).toBe(true);
  });

  it('should generate index.html when no markdown files exist', () => {
    build(testContentDir, testOutputDir);
    const indexPath = path.join(testOutputDir, 'index.html');
    expect(fs.existsSync(indexPath)).toBe(true);
    const content = fs.readFileSync(indexPath, 'utf-8');
    expect(content).toContain('No pages found');
  });

  it('should parse markdown and create HTML files', () => {
    const mdContent = `---
title: Test Post
---
# Test Post
This is test content.`;

    fs.writeFileSync(path.join(testContentDir, 'test.md'), mdContent);
    build(testContentDir, testOutputDir);

    const htmlPath = path.join(testOutputDir, 'test.html');
    expect(fs.existsSync(htmlPath)).toBe(true);

    const html = fs.readFileSync(htmlPath, 'utf-8');
    expect(html).toContain('Test Post');
    expect(html).toContain('This is test content');
  });

  it('should generate index.html with links to all pages', () => {
    const post1 = `---
title: First Post
---
Content 1`;

    const post2 = `---
title: Second Post
date: 2024-01-15
---
Content 2`;

    fs.writeFileSync(path.join(testContentDir, 'first.md'), post1);
    fs.writeFileSync(path.join(testContentDir, 'second.md'), post2);
    build(testContentDir, testOutputDir);

    const indexPath = path.join(testOutputDir, 'index.html');
    const index = fs.readFileSync(indexPath, 'utf-8');

    expect(index).toContain('first.html');
    expect(index).toContain('second.html');
    expect(index).toContain('First Post');
    expect(index).toContain('Second Post');
    expect(index).toContain('2024-01-15');
  });

  it('should include back link in page HTML', () => {
    const mdContent = `---
title: Test
---
Content`;

    fs.writeFileSync(path.join(testContentDir, 'test.md'), mdContent);
    build(testContentDir, testOutputDir);

    const html = fs.readFileSync(path.join(testOutputDir, 'test.html'), 'utf-8');
    expect(html).toContain('← Home');
    expect(html).toContain('/index.html');
  });

  it('should handle markdown with code blocks', () => {
    const mdContent = `---
title: Code Post
---
\`\`\`javascript
console.log('hello');
\`\`\``;

    fs.writeFileSync(path.join(testContentDir, 'code.md'), mdContent);
    build(testContentDir, testOutputDir);

    const html = fs.readFileSync(path.join(testOutputDir, 'code.html'), 'utf-8');
    expect(html).toContain('console.log');
  });

  it('should handle markdown with lists', () => {
    const mdContent = `---
title: Lists
---
- Item 1
- Item 2
- Item 3`;

    fs.writeFileSync(path.join(testContentDir, 'lists.md'), mdContent);
    build(testContentDir, testOutputDir);

    const html = fs.readFileSync(path.join(testOutputDir, 'lists.html'), 'utf-8');
    expect(html).toContain('Item 1');
    expect(html).toContain('Item 2');
    expect(html).toContain('Item 3');
  });

  it('should include date in page HTML if present', () => {
    const mdContent = `---
title: Dated Post
date: 2024-01-15
---
Content`;

    fs.writeFileSync(path.join(testContentDir, 'dated.md'), mdContent);
    build(testContentDir, testOutputDir);

    const html = fs.readFileSync(path.join(testOutputDir, 'dated.html'), 'utf-8');
    expect(html).toContain('2024-01-15');
    expect(html).toContain('class="date"');
  });

  it('should include tags in page HTML if present', () => {
